UPDATE t_user_point
SET point = point + #{point}, update_time = NOW()
WHERE user_id = #{userId}

UPDATE t_user_point
SET point = point - #{point}, update_time = NOW()
WHERE user_id = #{userId} AND point >= #{point}

UPDATE t_user_point
SET frozen_point = frozen_point + #{point}, update_time = NOW()
WHERE user_id = #{userId}

UPDATE t_user_point
SET frozen_point = frozen_point - #{point}, update_time = NOW()
WHERE user_id = #{userId} AND frozen_point >= #{point}

UPDATE t_user_point
SET total_point = total_point + #{point}, update_time = NOW()
WHERE user_id = #{userId}
